#!/bin/bash
# Print the top 3 most frequent IPs from access.log,
# ties broken by first appearance in the log.
awk '{
    if (!($1 in count)) {
        order[++n] = $1
    }
    count[$1]++
}
END {
    # Simple selection sort: pick max count, tie -> earliest in order[]
    for (i = 1; i <= n && i <= 3; i++) {
        best = ""
        for (j = 1; j <= n; j++) {
            ip = order[j]
            if (ip in used) continue
            if (best == "" || count[ip] > count[best] || (count[ip] == count[best] && j < bpos)) {
                best = ip
                bpos = j
            }
        }
        used[best] = 1
        print best
    }
}' access.log
